CREATE TABLE dwg_drawing (id INTEGER PRIMARY KEY CHECK(id = 1), document_id INTEGER NOT NULL REFERENCES dwg_document(id) CHECK(document_id = 1));
CREATE TABLE dwg_drawing_layer (id INTEGER PRIMARY KEY, drawing_id INTEGER NOT NULL REFERENCES dwg_drawing(id) CHECK(drawing_id = 1), ordinal INTEGER NOT NULL CHECK(ordinal >= 0), name TEXT NOT NULL, color INTEGER NOT NULL CHECK(color BETWEEN 0 AND 255));
CREATE TABLE dwg_drawing_extmin (id INTEGER PRIMARY KEY, drawing_id INTEGER NOT NULL REFERENCES dwg_drawing(id) CHECK(drawing_id = 1), ordinal INTEGER NOT NULL CHECK(ordinal >= 0), value_class TEXT NOT NULL CHECK(value_class IN ('finite','negative_zero','nan','positive_infinity','negative_infinity')), value_ieee754_bits INTEGER, value REAL CHECK((value_class = 'finite' AND value IS NOT NULL AND abs(value) <= 1.7976931348623157e308) OR (value_class != 'finite' AND value IS NULL)));
CREATE TABLE dwg_drawing_extmax (id INTEGER PRIMARY KEY, drawing_id INTEGER NOT NULL REFERENCES dwg_drawing(id) CHECK(drawing_id = 1), ordinal INTEGER NOT NULL CHECK(ordinal >= 0), value_class TEXT NOT NULL CHECK(value_class IN ('finite','negative_zero','nan','positive_infinity','negative_infinity')), value_ieee754_bits INTEGER, value REAL CHECK((value_class = 'finite' AND value IS NOT NULL AND abs(value) <= 1.7976931348623157e308) OR (value_class != 'finite' AND value IS NULL)));
CREATE TABLE dwg_object (
  id INTEGER PRIMARY KEY, drawing_id INTEGER NOT NULL REFERENCES dwg_drawing(id) CHECK(drawing_id = 1), ordinal INTEGER NOT NULL CHECK(ordinal >= 0),
  handle_high INTEGER NOT NULL CHECK(handle_high BETWEEN 0 AND 4294967295), handle_low INTEGER NOT NULL CHECK(handle_low BETWEEN 0 AND 4294967295),
  type_code INTEGER NOT NULL CHECK(type_code BETWEEN 0 AND 65535), class_name TEXT NOT NULL, category TEXT NOT NULL CHECK(category IN ('entity','table_control','table_record','dictionary','object','custom')),
  owner_handle_high INTEGER CHECK(owner_handle_high BETWEEN 0 AND 4294967295), owner_handle_low INTEGER CHECK(owner_handle_low BETWEEN 0 AND 4294967295),
  extension_dictionary_handle_high INTEGER CHECK(extension_dictionary_handle_high BETWEEN 0 AND 4294967295), extension_dictionary_handle_low INTEGER CHECK(extension_dictionary_handle_low BETWEEN 0 AND 4294967295),
  body_kind TEXT CHECK(body_kind IN ('dictionary','table_control','table_record','xrecord','entity','associative_dependency','associative_value_dependency','associative_geometry_dependency','block_grip_location_component','dynamic_block_proxy_node','associative_variable','associative_dimension_dependency_body','visual_style','block_parameter_dependency_body','block_representation_data','dynamic_block_purge_preventer','evaluation_graph','block_flip_parameter','block_visibility_parameter','placeholder','dictionary_variable','annotation_scale','sort_entities_table','table_style','mline_style','mleader_style','material','block_move_action','assoc_network','assoc_2d_constraint_group','block_linear_parameter','block_linear_grip','block_flip_grip','block_visibility_grip','block_alignment_parameter','block_alignment_grip','block_stretch_action','block_scale_action','block_flip_action','block_base_point_parameter','block_vertical_constraint_parameter','block_horizontal_constraint_parameter','layout')),
  CHECK((owner_handle_high IS NULL) = (owner_handle_low IS NULL)), CHECK((extension_dictionary_handle_high IS NULL) = (extension_dictionary_handle_low IS NULL))
);
CREATE TABLE dwg_object_reactor_handle (id INTEGER PRIMARY KEY, object_id INTEGER NOT NULL REFERENCES dwg_object(id), ordinal INTEGER NOT NULL CHECK(ordinal >= 0), handle_high INTEGER NOT NULL CHECK(handle_high BETWEEN 0 AND 4294967295), handle_low INTEGER NOT NULL CHECK(handle_low BETWEEN 0 AND 4294967295));
CREATE TABLE dwg_object_referenced_handle (id INTEGER PRIMARY KEY, object_id INTEGER NOT NULL REFERENCES dwg_object(id), ordinal INTEGER NOT NULL CHECK(ordinal >= 0), handle_high INTEGER NOT NULL CHECK(handle_high BETWEEN 0 AND 4294967295), handle_low INTEGER NOT NULL CHECK(handle_low BETWEEN 0 AND 4294967295));
CREATE TABLE dwg_extended_entity_data (id INTEGER PRIMARY KEY, object_id INTEGER NOT NULL REFERENCES dwg_object(id), ordinal INTEGER NOT NULL CHECK(ordinal >= 0), application_handle_high INTEGER NOT NULL CHECK(application_handle_high BETWEEN 0 AND 4294967295), application_handle_low INTEGER NOT NULL CHECK(application_handle_low BETWEEN 0 AND 4294967295));
CREATE TABLE dwg_dictionary (
  id INTEGER PRIMARY KEY REFERENCES dwg_object(id), cloning_flag INTEGER NOT NULL CHECK(cloning_flag BETWEEN 0 AND 65535), hard_owner INTEGER NOT NULL CHECK(hard_owner IN (0,1)),
  default_entry_handle_high INTEGER CHECK(default_entry_handle_high BETWEEN 0 AND 4294967295), default_entry_handle_low INTEGER CHECK(default_entry_handle_low BETWEEN 0 AND 4294967295),
  CHECK((default_entry_handle_high IS NULL) = (default_entry_handle_low IS NULL))
);
CREATE TABLE dwg_dictionary_entry (id INTEGER PRIMARY KEY, dictionary_id INTEGER NOT NULL REFERENCES dwg_dictionary(id), ordinal INTEGER NOT NULL CHECK(ordinal >= 0), name TEXT NOT NULL, handle_high INTEGER NOT NULL CHECK(handle_high BETWEEN 0 AND 4294967295), handle_low INTEGER NOT NULL CHECK(handle_low BETWEEN 0 AND 4294967295));
CREATE TABLE dwg_table_control (
  id INTEGER PRIMARY KEY REFERENCES dwg_object(id), kind TEXT NOT NULL CHECK(kind IN ('block','layer','text_style','linetype','view','ucs','viewport','registered_application','dimension_style')),
  model_space_handle_high INTEGER CHECK(model_space_handle_high BETWEEN 0 AND 4294967295), model_space_handle_low INTEGER CHECK(model_space_handle_low BETWEEN 0 AND 4294967295),
  paper_space_handle_high INTEGER CHECK(paper_space_handle_high BETWEEN 0 AND 4294967295), paper_space_handle_low INTEGER CHECK(paper_space_handle_low BETWEEN 0 AND 4294967295),
  by_block_handle_high INTEGER CHECK(by_block_handle_high BETWEEN 0 AND 4294967295), by_block_handle_low INTEGER CHECK(by_block_handle_low BETWEEN 0 AND 4294967295),
  by_layer_handle_high INTEGER CHECK(by_layer_handle_high BETWEEN 0 AND 4294967295), by_layer_handle_low INTEGER CHECK(by_layer_handle_low BETWEEN 0 AND 4294967295),
  CHECK((model_space_handle_high IS NULL) = (model_space_handle_low IS NULL)), CHECK((paper_space_handle_high IS NULL) = (paper_space_handle_low IS NULL)),
  CHECK((kind = 'block') OR (model_space_handle_high IS NULL AND paper_space_handle_high IS NULL)),
  CHECK((kind = 'linetype' AND by_block_handle_high IS NOT NULL AND by_block_handle_low IS NOT NULL AND by_layer_handle_high IS NOT NULL AND by_layer_handle_low IS NOT NULL) OR (kind != 'linetype' AND by_block_handle_high IS NULL AND by_block_handle_low IS NULL AND by_layer_handle_high IS NULL AND by_layer_handle_low IS NULL))
);
CREATE TABLE dwg_table_control_entry (id INTEGER PRIMARY KEY, control_id INTEGER NOT NULL REFERENCES dwg_table_control(id), ordinal INTEGER NOT NULL CHECK(ordinal >= 0), handle_high INTEGER CHECK(handle_high BETWEEN 0 AND 4294967295), handle_low INTEGER CHECK(handle_low BETWEEN 0 AND 4294967295), CHECK((handle_high IS NULL) = (handle_low IS NULL)));
CREATE TABLE dwg_dimension_style_control_additional_handle (id INTEGER PRIMARY KEY, control_id INTEGER NOT NULL REFERENCES dwg_table_control(id), ordinal INTEGER NOT NULL CHECK(ordinal >= 0), handle_high INTEGER NOT NULL CHECK(handle_high BETWEEN 0 AND 4294967295), handle_low INTEGER NOT NULL CHECK(handle_low BETWEEN 0 AND 4294967295));
CREATE TABLE dwg_xrecord (id INTEGER PRIMARY KEY REFERENCES dwg_object(id), cloning_flag INTEGER NOT NULL CHECK(cloning_flag BETWEEN 0 AND 65535));
CREATE TABLE dwg_xrecord_object_id_handle (id INTEGER PRIMARY KEY, xrecord_id INTEGER NOT NULL REFERENCES dwg_xrecord(id), ordinal INTEGER NOT NULL CHECK(ordinal >= 0), handle_high INTEGER NOT NULL CHECK(handle_high BETWEEN 0 AND 4294967295), handle_low INTEGER NOT NULL CHECK(handle_low BETWEEN 0 AND 4294967295));
CREATE TABLE dwg_xrecord_value (
  id INTEGER PRIMARY KEY, extended_data_id INTEGER REFERENCES dwg_extended_entity_data(id), xrecord_id INTEGER REFERENCES dwg_xrecord(id), ordinal INTEGER NOT NULL CHECK(ordinal >= 0), group_code INTEGER NOT NULL CHECK(group_code BETWEEN -32768 AND 32767),
  kind TEXT NOT NULL CHECK(kind IN ('string','real','boolean','integer8','integer16','integer32','integer64','point3d','binary','handle','object_id')),
  text_value TEXT, real_value_class TEXT CHECK(real_value_class IN ('finite','negative_zero','nan','positive_infinity','negative_infinity')), real_value_ieee754_bits INTEGER, real_value REAL CHECK((real_value_class IS NULL AND real_value IS NULL) OR (real_value_class IS NOT NULL AND ((real_value_class = 'finite' AND real_value IS NOT NULL AND abs(real_value) <= 1.7976931348623157e308) OR (real_value_class != 'finite' AND real_value IS NULL)))), integer_value INTEGER, point_x_class TEXT CHECK(point_x_class IN ('finite','negative_zero','nan','positive_infinity','negative_infinity')), point_x_ieee754_bits INTEGER, point_x REAL CHECK((point_x_class IS NULL AND point_x IS NULL) OR (point_x_class IS NOT NULL AND ((point_x_class = 'finite' AND point_x IS NOT NULL AND abs(point_x) <= 1.7976931348623157e308) OR (point_x_class != 'finite' AND point_x IS NULL)))), point_y_class TEXT CHECK(point_y_class IN ('finite','negative_zero','nan','positive_infinity','negative_infinity')), point_y_ieee754_bits INTEGER, point_y REAL CHECK((point_y_class IS NULL AND point_y IS NULL) OR (point_y_class IS NOT NULL AND ((point_y_class = 'finite' AND point_y IS NOT NULL AND abs(point_y) <= 1.7976931348623157e308) OR (point_y_class != 'finite' AND point_y IS NULL)))), point_z_class TEXT CHECK(point_z_class IN ('finite','negative_zero','nan','positive_infinity','negative_infinity')), point_z_ieee754_bits INTEGER, point_z REAL CHECK((point_z_class IS NULL AND point_z IS NULL) OR (point_z_class IS NOT NULL AND ((point_z_class = 'finite' AND point_z IS NOT NULL AND abs(point_z) <= 1.7976931348623157e308) OR (point_z_class != 'finite' AND point_z IS NULL)))),
  handle_high INTEGER CHECK(handle_high BETWEEN 0 AND 4294967295), handle_low INTEGER CHECK(handle_low BETWEEN 0 AND 4294967295),
  CHECK((extended_data_id IS NOT NULL AND xrecord_id IS NULL) OR (extended_data_id IS NULL AND xrecord_id IS NOT NULL)),
  CHECK((kind = 'string' AND text_value IS NOT NULL) OR (kind != 'string' AND text_value IS NULL)),
  CHECK((kind = 'real' AND real_value_class IS NOT NULL) OR (kind != 'real' AND real_value_class IS NULL)),
  CHECK((kind = 'boolean' AND integer_value IS NOT NULL AND integer_value IN (0,1)) OR (kind = 'integer8' AND integer_value IS NOT NULL AND integer_value BETWEEN -128 AND 127) OR (kind = 'integer16' AND integer_value IS NOT NULL AND integer_value BETWEEN -32768 AND 32767) OR (kind = 'integer32' AND integer_value IS NOT NULL AND integer_value BETWEEN -2147483648 AND 2147483647) OR (kind = 'integer64' AND integer_value IS NOT NULL) OR (kind NOT IN ('boolean','integer8','integer16','integer32','integer64') AND integer_value IS NULL)),
  CHECK((kind = 'point3d' AND point_x_class IS NOT NULL AND point_y_class IS NOT NULL AND point_z_class IS NOT NULL) OR (kind != 'point3d' AND point_x_class IS NULL AND point_y_class IS NULL AND point_z_class IS NULL)),
  CHECK((kind IN ('handle','object_id') AND handle_high IS NOT NULL AND handle_low IS NOT NULL) OR (kind NOT IN ('handle','object_id') AND handle_high IS NULL AND handle_low IS NULL))
);
CREATE TABLE dwg_xrecord_binary_octet (id INTEGER PRIMARY KEY, value_id INTEGER NOT NULL REFERENCES dwg_xrecord_value(id), ordinal INTEGER NOT NULL CHECK(ordinal >= 0), value INTEGER NOT NULL CHECK(value BETWEEN 0 AND 255));
